class Solution {
public:
    int mctFromLeafValues(vector<int>& arr) {
        int res = 0;
        vector<int> st = {INT_MAX};
        for (int x : arr) {
            while (st.back() <= x) {
                int mid = st.back();
                st.pop_back();
                res += mid * min(st.back(), x);
            }
            st.push_back(x);
        }
        while (st.size() > 2) {
            int top = st.back();
            st.pop_back();
            res += top * st.back();
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int mctFromLeafValues(int[] arr) {
        int res = 0;
        Deque<Integer> st = new ArrayDeque<>();
        st.push(Integer.MAX_VALUE);
        for (int x : arr) {
            while (st.peek() <= x) {
                int mid = st.pop();
                res += mid * Math.min(st.peek(), x);
            }
            st.push(x);
        }
        while (st.size() > 2) {
            res += st.pop() * st.peek();
        }
        return res;
    }
}

var mctFromLeafValues = function(arr) {
    let res = 0;
    const stack = [Infinity];
    for (const x of arr) {
        while (stack[stack.length - 1] <= x) {
            const mid = stack.pop();
            res += mid * Math.min(stack[stack.length - 1], x);
        }
        stack.push(x);
    }
    while (stack.length > 2) {
        res += stack.pop() * stack[stack.length - 1];
    }
    return res;
};
